    sorted_unique_numbers = sorted(unique_numbers)
    count = len(sorted_unique_numbers)
    return (count, sorted_unique_numbers)

def max_energy(beads):
    # Initialize a dictionary to store the maximum energy for each possible merging order
    energies = {}

    # Consider all possible merging orders
    for i in range(len(beads)):
        for j in range(i+1, len(beads)):
            # Compute the maximum energy obtainable by merging the bead at index i with the bead at index j
            energy = beads[i] * beads[j] * beads[(j+1) % len(beads)]

            # Update the maximum energy for this merging order
            if j in energies:
                energies[j] = max(energies[j], energy)
            else:
                energies[j] = energy

    # Return the maximum energy that can be obtained by optimally merging all beads
    return max(energies.values())

def polynomial_to_string(n, coeffs):
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    result = ''
    for i in range(len(coeffs)):
        coefficient = coeffs[i]
        if coefficient == 0:
            continue
        degree = n - i
        if degree == 1:
            term = 'x'
        elif degree > 1:
            term = 'x^' + str(degree)
        else:
            term = ''
        if abs(coefficient) != 1 or term != 'x':
            term += str(abs(coefficient))
        if coefficient < 0:
            term = '-' + term
        if i != 0 or coefficient != 0:
            result += term + '+'
    return result[:-1]

def decode(encoded, original, message):
    # Initialize the mapping from encoded to original letters
    mapping = {}
    for i in range(len(original)):
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
    # Check if the mapping is valid and all letters are represented
    if len(mapping) == len(encoded) and all(letter in mapping for letter in original):
        # Decode the message using the mapping
        return ''.join(mapping[letter] for letter in message)
    else:
        return "Failed"

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n > last:
        return 0
    if n in memo:
        return memo[n]
    count = 0
    for i in range(1, last + 1):
        if i <= n and i <= last // 2:
            count += count_sequences(n, i, memo)
    memo[last] = count
    return count

def count_coprime_pairs(x0, y0):
    count = 0
    quotient = y0 // x0
    for a in range(1, quotient + 1):
        b = y0 // a
        if gcd(a, b) == 1:
            if a == b:
                count += 1
            else:
                count += 2
    return count

def find_min_n_greater_than_k(k: int) -> int:
    if k < 1:
        raise ValueError("k must be a positive integer")

    n = 2
    sum = 1 + 1 / 2
    while sum <= k:
        n += 1
        sum += 1 / n

    return n

def generate_numbers(n, rules):
    unique_numbers = set()
    queue = [(n, 0)]

    while queue:
        number, depth = queue.pop(0)
        unique_numbers.add(number)

        for rule in rules:
            x, y = rule
            if number % 10 == x:
                queue.append((number * 10 + y, depth + 1))

    return len(unique_numbers)

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    return (catalan_number(n-1) * catalan_number(n-2)) % 1_000_000_007

