def jinjin_savings_plan(budgets):
    total_amount = 0

    for i, budget in enumerate(budgets):
        if budget - 100 < 0:
            return -i

        amount_to_save = budget - 100
        total_amount += amount_to_save
        total_amount *= 1.2

    return total_amount

def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    if n == 2:
        return 6
    if n == 3:
        return 14

    moves = 0
    for i in range(n - 1):
        moves += (2 ** i) * (2 * i + 1)
    return moves + 2 ** n - 1

def total_smoked_cigarettes(n, k):
    total = n
    while n >= k:
        total += n // k
        n = n // k
    return total
